#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Admin sign-in setup: GitHub OAuth apps and the Admin's environment variables,
# locally (.env.local) and on Vercel (Production). Run from anywhere:
#   bash scripts/wizards/admin-github-oauth.sh
cd "$(dirname "${BASH_SOURCE[0]}")/../.."
ENV_FILE=".env.local"

PROD_ORIGIN="https://imjustlucas.dev"
LOCAL_ORIGIN="http://localhost:3000"
CALLBACK_PATH="/admin/auth/callback"

TOTAL_STAGES=7

# vercel_env NAME VALUE [--sensitive] sets a Production variable on Vercel,
# overwriting any previous value. The value goes through stdin, never argv.
vercel_env() {
  local name="$1" value="$2"; shift 2
  if printf '%s' "$value" | "${VERCEL[@]}" env add "$name" production --force "$@" >/dev/null 2>&1; then
    printf '  %s✓ set%s Vercel Production variable %s\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Vercel Production variable $name (Vercel → Project → Settings → Environment Variables)")
    warn "couldn't set $name on Vercel; set it in the dashboard"
  fi
}

banner "Admin sign-in: GitHub OAuth + environment variables"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Your GitHub account identifier"
say "Only this GitHub account gets into the Admin. It's the numeric id, not the"
say "login (a login can be renamed, the id never changes)."
detected=""
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  detected=$(gh api user -q .id 2>/dev/null || true)
fi
if [[ -n "$detected" ]]; then
  note "gh is signed in as $(gh api user -q .login 2>/dev/null || echo '?'), id $detected."
  note "Paste that id, or press Enter on an empty prompt to use it."
else
  open_url "https://api.github.com/users/ImJustLucas"
  step "Copy the number after \"id\": near the top of that page."
fi
OWNER_GITHUB_ID=""
ask OWNER_GITHUB_ID "Owner GitHub id:" || true
[[ -z "$OWNER_GITHUB_ID" && -n "$detected" ]] && OWNER_GITHUB_ID="$detected"
until [[ "$OWNER_GITHUB_ID" =~ ^[0-9]+$ ]]; do
  warn "that's not a number"
  ask OWNER_GITHUB_ID "Owner GitHub id:"
done
write_env OWNER_GITHUB_ID "$OWNER_GITHUB_ID"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub OAuth app for local development"
say "One OAuth app per environment: GitHub only sends you back to the callback"
say "URL registered on the app. This one is for $LOCAL_ORIGIN."
open_url "https://github.com/settings/applications/new"
step "Application name:           imjustlucas.dev Admin (local)"
step "Homepage URL:               $LOCAL_ORIGIN"
step "Authorization callback URL: $LOCAL_ORIGIN$CALLBACK_PATH"
step "Leave \"Enable Device Flow\" unticked, then click \"Register application\"."
note "No scope to tick here: the Admin asks for public_repo itself at sign-in."
note "Created it on a previous run? Open it from Settings → Developer settings"
note "→ OAuth Apps instead (Enter keeps the values already saved)."
pause "Press Enter once the app is registered."
step "Copy the Client ID shown on the app's page."
ask GITHUB_CLIENT_ID "Local Client ID:"
step "Click \"Generate a new client secret\" and copy it (GitHub shows it once)."
ask_secret GITHUB_CLIENT_SECRET "Local client secret:"
write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Local session secret"
say "The session cookie is encrypted with SESSION_SECRET (at least 32 characters)."
existing_secret=$(_existing SESSION_SECRET || true)
if [[ ${#existing_secret} -ge 32 ]]; then
  note "$ENV_FILE already has one; keeping it (changing it signs you out)."
else
  write_env SESSION_SECRET "$(openssl rand -base64 32)"
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub OAuth app for production"
DO_PROD=1
confirm "Set up production ($PROD_ORIGIN) now? No ends after the local setup" || DO_PROD=0
if (( DO_PROD )); then
  open_url "https://github.com/settings/applications/new"
  step "Application name:           imjustlucas.dev Admin"
  step "Homepage URL:               $PROD_ORIGIN"
  step "Authorization callback URL: $PROD_ORIGIN$CALLBACK_PATH"
  step "Leave \"Enable Device Flow\" unticked, then click \"Register application\"."
  pause "Press Enter once the app is registered."
  step "Copy the Client ID shown on the app's page."
  ask PROD_GITHUB_CLIENT_ID "Production Client ID:"
  step "Click \"Generate a new client secret\" and copy it."
  ask_secret PROD_GITHUB_CLIENT_SECRET "Production client secret:"
  note "These stay in memory only: they go to Vercel, not to $ENV_FILE."
  pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Vercel CLI"
if (( DO_PROD )); then
  if command -v vercel >/dev/null 2>&1; then VERCEL=(vercel); else VERCEL=(pnpm dlx vercel@latest); fi
  note "Using: ${VERCEL[*]}"
  if ! "${VERCEL[@]}" whoami >/dev/null 2>&1; then
    say "Sign in to Vercel (it opens your browser)."
    "${VERCEL[@]}" login
  fi
  if [[ ! -f .vercel/project.json ]]; then
    say "Link this folder to the imjustlucas.dev Vercel project (pick the existing one)."
    "${VERCEL[@]}" link
  fi
  note "Linked: $(grep -o '"projectName":"[^"]*"' .vercel/project.json 2>/dev/null || echo 'see .vercel/project.json')"
else
  note "Skipped (no production setup this run)."
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel Production environment variables"
if (( DO_PROD )); then
  say "Will set on Vercel (Production), replacing any previous values:"
  step "GITHUB_CLIENT_ID, GITHUB_CLIENT_SECRET (the production OAuth app)"
  step "SESSION_SECRET (a new random one, different from the local one)"
  step "OWNER_GITHUB_ID=$OWNER_GITHUB_ID"
  step "AUTH_REDIRECT_URI=$PROD_ORIGIN$CALLBACK_PATH"
  if confirm "Write these to Vercel now?"; then
    vercel_env GITHUB_CLIENT_ID "$PROD_GITHUB_CLIENT_ID"
    vercel_env GITHUB_CLIENT_SECRET "$PROD_GITHUB_CLIENT_SECRET" --sensitive
    vercel_env SESSION_SECRET "$(openssl rand -base64 32)" --sensitive
    vercel_env OWNER_GITHUB_ID "$OWNER_GITHUB_ID"
    vercel_env AUTH_REDIRECT_URI "$PROD_ORIGIN$CALLBACK_PATH"
  else
    SKIPPED+=("Vercel Production variables (re-run this wizard)")
  fi
else
  note "Skipped (no production setup this run)."
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Try it"
say "Locally:"
step "pnpm dev, then open $LOCAL_ORIGIN/admin and click \"Se connecter avec GitHub\"."
step "GitHub asks to grant access to public repositories; accept, and the empty"
step "Admin home appears."
if (( DO_PROD )); then
  say "Production (new variables only apply to new deployments):"
  step "Vercel → imjustlucas.dev → Deployments → latest Production → ⋯ → Redeploy,"
  step "or push to main. Then open $PROD_ORIGIN/admin and sign in."
fi
note "To cut access later: GitHub → Settings → Applications → Authorized OAuth Apps"
note "→ Revoke; changing SESSION_SECRET signs every session out."
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
